<script lang="ts">
  import { entries, deleteEntry, formatMoney, formatDate, type AccountOverview, type EntryRow, type EntriesResult } from './lib/api';
  import EntrySheet from './EntrySheet.svelte';
  let { accounts, accountId, heading, version, refresh }: {accounts: AccountOverview[]; accountId?: number; heading: string; version: string; refresh: () => void} = $props();
  let search = $state(''); let debounced = $state(''); let limit = $state(500); let data = $state<EntriesResult>({rows:[], total:0, sum:0});
  let error = $state(''); let selection = $state<number | null>(null); let editing = $state<EntryRow | null>(null); let sheet = $state(false); let expense = $state(true); let menu = $state<{x:number; y:number; row:EntryRow} | null>(null); let request = 0; let localVersion = $state(0);
  $effect(() => { const text = search; const timer = setTimeout(() => { debounced = text; limit = 500; }, 150); return () => clearTimeout(timer); });
  $effect(() => { const filter = { accountId, search: debounced, limit }; void version; void localVersion; const id = ++request; void entries(filter).then(v => { if (id === request) { data = v; error = ''; } }).catch(e => { if (id === request) error = String(e); }); });
  function add(isExpense: boolean) { expense = isExpense; editing = null; sheet = true; menu = null; }
  function edit(row: EntryRow) { editing = row; sheet = true; menu = null; }
  async function remove(row: EntryRow) { menu = null; if (!confirm('¿Eliminar este movimiento?')) return; try { await deleteEntry(row.id); selection = null; localVersion++; refresh(); } catch (e) { error = String(e); } }
  function keys(e: KeyboardEvent) { if (sheet) return; const target = e.target as HTMLElement; if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'n') { e.preventDefault(); add(!e.shiftKey); } else if ((e.key === 'Delete' || e.key === 'Backspace') && !['INPUT','TEXTAREA','SELECT'].includes(target.tagName) && selection !== null) { const row = data.rows.find(r => r.id === selection); if (row) { e.preventDefault(); void remove(row); } } else if (e.key === 'Escape') menu = null; }
</script>
<svelte:window onkeydown={keys}/>
<div class="screen"><div><h1>{heading}</h1><p>Tu historial de movimientos</p></div>
  <section class="card summary"><div><p>{debounced ? 'Total de la búsqueda' : 'Saldo de los movimientos'}</p><strong>{formatMoney(data.sum)}</strong></div><div class="right"><p>{data.total} movimientos</p><div class="actions"><button class="expense-button" title="Agregar gasto (⌘N)" onclick={() => add(true)}>Agregar gasto</button><button class="income-button" title="Agregar ingreso (⇧⌘N)" onclick={() => add(false)}>Agregar ingreso</button></div></div></section>
  <label class="search">Buscar comercio, categoría o nota<input bind:value={search} placeholder="Buscar comercio, categoría o nota"/></label>
  {#if error}<p role="alert" class="error">{error}</p>{/if}
  <section class="card tablewrap">{#if data.total === 0}<div class="empty"><h2>Sin movimientos</h2><p>Agrega uno con ⌘N o importa desde Actual en Archivo.</p></div>{:else}<table><thead><tr><th>Fecha</th>{#if accountId === undefined && accounts.length > 1}<th>Cuenta</th>{/if}<th>Comercio</th><th>Categoría</th><th>Notas</th><th>Monto</th></tr></thead><tbody>{#each data.rows as row (row.id)}<tr class:selected={selection === row.id} onclick={() => { selection = row.id; menu = null; }} ondblclick={() => edit(row)} oncontextmenu={(e) => {e.preventDefault(); selection = row.id; menu = {x:e.clientX, y:e.clientY, row};}}><td>{formatDate(row.date)}</td>{#if accountId === undefined && accounts.length > 1}<td>{row.accountName ?? ''}</td>{/if}<td>{row.payeeName ?? ''}</td><td>{#if row.categoryName}{row.categoryName}{:else}<span class="warning" title="Sin categoría no cuenta en el presupuesto">⚠ Sin categoría</span>{/if}</td><td>{row.notes}</td><td class:expense={row.amount < 0} class:income={row.amount >= 0}>{formatMoney(row.amount)}</td></tr>{/each}</tbody></table>{#if data.rows.length < data.total}<button class="more" onclick={() => limit += 500}>Mostrar más</button>{/if}{/if}</section>
</div>
{#if menu}<div class="menu" style:left={`${menu.x}px`} style:top={`${menu.y}px`}><button onclick={() => menu && edit(menu.row)}>Editar</button><button onclick={() => menu && remove(menu.row)}>Eliminar</button></div>{/if}
{#if sheet}<EntrySheet {accounts} {accountId} {editing} startExpense={expense} close={() => sheet = false} saved={() => {sheet = false; localVersion++; refresh();}}/>{/if}
<style>
.screen{display:grid;gap:20px;max-width:1500px;margin:auto}h1,h2,p{margin:0}p{color:var(--muted);margin-top:5px}.card{padding:20px;background:var(--card);border:1px solid var(--border);border-radius:18px}.summary,.actions{display:flex;align-items:center;justify-content:space-between;gap:10px}.summary strong{font-size:2rem}.right{text-align:right}.actions{margin-top:12px}.search{display:grid;gap:5px;font-size:.9rem}.search input{font:inherit;color:inherit;background:var(--card);border:1px solid var(--border);border-radius:8px;padding:10px}.tablewrap{overflow:auto;padding:0}.empty{text-align:center;padding:70px 20px}table{border-collapse:collapse;width:100%;font-size:.9rem}th,td{padding:12px;text-align:left;border-bottom:1px solid var(--border)}th{color:var(--muted)}tr.selected{background:var(--canvas)}td:last-child,th:last-child{text-align:right;white-space:nowrap}.expense,.error{color:var(--coral)}.income{color:var(--emerald)}.warning{color:var(--amber)}button{font:inherit;cursor:pointer;border:0;border-radius:999px;padding:9px 16px}.expense-button{background:var(--expense-fill);color:white}.income-button{background:var(--income-fill);color:white}.more{margin:16px;background:var(--canvas);color:inherit}.menu{position:fixed;z-index:5;display:grid;padding:5px;background:var(--card);border:1px solid var(--border);border-radius:8px;box-shadow:0 4px 20px #0003}.menu button{border-radius:5px;background:transparent;color:inherit;text-align:left}.menu button:hover{background:var(--canvas)}@media(max-width:700px){.summary{align-items:flex-start;flex-direction:column}.right{text-align:left}}
</style>
